#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Res { Void, Val(f64), Undef, Nan, Threw }

#[derive(Clone, Copy, Debug)]
pub struct Op { pub kind: u8, pub a: f64, pub b: f64, pub res: Res }

pub struct MinHeapScenario {
    pub name: &'static str,
    pub cap: f64,
    pub ops: &'static [Op],
    pub heap: &'static [i32],
    pub pri_bits: &'static [u32],
    pub size: i64,
    pub capacity: usize,
}

pub struct BucketScenario {
    pub name: &'static str,
    pub max_p: f64,
    pub ops: &'static [Op],
    pub sizes: &'static [i32],
    pub stamps: &'static [u32],
    pub keys: &'static [i64],
    pub min_bucket: f64,
    pub size: f64,
    pub stamp: u64,
}

pub struct FlatHeapScenario {
    pub name: &'static str,
    pub cap: usize,
    pub ops: &'static [Op],
    pub pri_bits: &'static [u32],
    pub tiles: &'static [Option<f64>],
    pub len: usize,
}

/// Grid-BFS scenario: mode 0 explore-all, 1 blocker invalid, 2
/// blocker rejected (null), 3 blocker found (returns 42). When the
/// visit stream is longer than the inline cap, `order`/`dists` are
/// empty and the stream is pinned by sampled (index, node, dist)
/// triples covering the Uint16 wrap boundary and both ends.
pub struct BfsScenario {
    pub name: &'static str,
    pub w: i64,
    pub h: i64,
    pub s0: i64,
    pub s1: i64,
    pub max_d: f64,
    pub mode: u8,
    pub blocker: i64,
    pub nvisits: usize,
    pub samples: &'static [(i64, i64, i64)],
    pub order: &'static [i64],
    pub dists: &'static [i64],
    pub found: i64,
    pub stamp_after: u64,
}

