/// A* scenario: GridAdapter parameters, one findPath call (or `runs`
/// calls for reuse scenarios), the returned path (`None` = TS null),
/// and the full stamp-tracked arrays after the last call.
pub struct AStarScenario {
    pub name: &'static str,
    pub w: f64,
    pub h: f64,
    pub blocked: &'static [f64],
    pub cc: f64,
    pub tp: f64,
    pub hk: u8,
    pub hs: f64,
    pub max_iter: Option<f64>,
    pub starts: &'static [f64],
    pub goal: f64,
    pub runs: usize,
    pub path: Option<&'static [f64]>,
    pub stamp_after: u64,
    pub closed: &'static [u32],
    pub gs_stamp: &'static [u32],
    pub g_score: &'static [u32],
    pub came_from: &'static [i32],
}

